using System.Reflection;

namespace DaisyBlazor.Components.Tests;

/// <summary>
/// Guards the generated Material Symbols catalogue (<c>Compat/Icons.cs</c>).
/// </summary>
/// <remarks>
/// The catalogue is generated by <c>scripts/generate-icons.py</c> from the official codepoints
/// list. Downstream code compiles against <c>Icons.Material.Filled.X</c>, so regeneration must
/// never rename a constant (a build break) and must never <i>repoint</i> one (far worse — the
/// glyph changes with no error anywhere). These are the 133 Filled and 2 Outlined
/// constants that existed before the catalogue was generated; every one must survive verbatim.
/// </remarks>
public class IconCatalogueTests
{
