    private static readonly (string Name, string Value)[] LegacyOutlined =
    [
        ("Error", "error"),
        ("NotificationsNone", "notifications_none"),
    ];

    private static IReadOnlyDictionary<string, string> Constants(Type type) =>
        type.GetFields(BindingFlags.Public | BindingFlags.Static | BindingFlags.FlattenHierarchy)
            .Where(f => f is { IsLiteral: true, IsInitOnly: false } && f.FieldType == typeof(string))
            .ToDictionary(f => f.Name, f => (string)f.GetRawConstantValue()!);

    [Fact]
    public void Every_pre_generation_Filled_constant_survives_with_the_same_value()
    {
        IReadOnlyDictionary<string, string> actual = Constants(typeof(Icons.Material.Filled));

        foreach ((string name, string value) in LegacyFilled)
        {
            actual.ShouldContainKey(name, $"constant {name} disappeared — that is a source-breaking change downstream");
            actual[name].ShouldBe(value, $"constant {name} was repointed; the rendered glyph would change silently");
        }
    }

    [Fact]
    public void Every_pre_generation_Outlined_constant_survives_with_the_same_value()
    {
        IReadOnlyDictionary<string, string> actual = Constants(typeof(Icons.Material.Outlined));

        foreach ((string name, string value) in LegacyOutlined)
        {
            actual.ShouldContainKey(name);
            actual[name].ShouldBe(value);
        }
    }

    [Fact]
    public void CheckCircleOutline_still_maps_to_check_circle()
    {
        // The one real collision: `check_circle_outline` is a legacy Material *Icons* ligature
        // whose PascalCase collides with this MudBlazor-compat alias. Consumers load the Material
        // Symbols *Outlined* font, where "check_circle" already renders outlined — so the alias
        // must keep winning, and the legacy ligature must stay dropped.
        Icons.Material.Filled.CheckCircleOutline.ShouldBe("check_circle");
    }

    [Fact]
    public void Catalogue_covers_the_full_symbol_set_not_a_curated_subset()
    {
        // The bug this fixes: a 135-entry hand-curated catalogue meant any icon outside it
        // failed to compile. Guard against silently regressing to a subset.
        Constants(typeof(Icons.Material.Filled)).Count.ShouldBeGreaterThan(4000);
    }

    [Fact]
    public void Digit_leading_ligatures_get_a_legal_identifier()
    {
        Icons.Material.Filled._10k.ShouldBe("10k");
    }
